// Exports the art the app draws to www/games/companero/arte.js. The app has no build step, so
// the generated file is committed; tools/test-companero.js fails if it falls behind design/.
// Usage: node design/companero/exportar.mjs
import fs from "node:fs";
import path from "node:path";
import { datosPrendas } from "./prendas.mjs";

const here = path.dirname(new URL(import.meta.url).pathname);
const dir = path.join(here, "cuerpos");
const cuerpos = Object.fromEntries(
  fs.readdirSync(dir).filter((f) => f.endsWith(".svg")).sort().map((f) => [f.slice(0, -4), fs.readFileSync(path.join(dir, f), "utf8")]),
);

// The designs (#7, #17) and each animal's natural colours, which disenos.js needs in the browser
const disenos = JSON.parse(fs.readFileSync(path.join(here, "disenos.json"), "utf8")).disenos;
const anclajes = JSON.parse(fs.readFileSync(path.join(here, "anclajes.json"), "utf8")).animales;
const colores = Object.fromEntries(Object.entries(anclajes).map(([id, a]) => [id, a.colores]));
const datos = { disenos, colores };

const salida = path.join(here, "../../www/games/companero/arte.js");
fs.writeFileSync(
  salida,
  `/* Generated by design/companero/exportar.mjs from design/companero/. Do not edit by hand:
   change the art in design/ and run the exporter again. */
(function (root) {
  var ARTE = { cuerpos: ${JSON.stringify(cuerpos, null, 2).replace(/\n/g, "\n  ")},
    disenos: ${JSON.stringify(datos, null, 2).replace(/\n/g, "\n  ")},
    prendas: ${JSON.stringify(datosPrendas, null, 2).replace(/\n/g, "\n  ")} };
  if (typeof module === 'object' && module.exports) module.exports = ARTE;
  else root.CompaneroArte = ARTE;
})(this);
`,
);
console.log(`arte.js: ${Object.keys(cuerpos).length} cuerpos, ${disenos.length} diseños, ${datosPrendas.catalogo.length} prendas`);
